import framebuf


class BitmapFont:
    """Draws text with a font module generated by tools/make_esp32_fonts.py."""

    def __init__(self, module):
        self.first = module.FIRST
        self.glyphs = module.GLYPHS
        self.data = module.DATA
        self.kerning = module.KERNING

    def glyph(self, char):
        index = ord(char) - self.first
        if not 0 <= index < len(self.glyphs):
            index = ord("?") - self.first
        return self.glyphs[index]

    def kern(self, first, second):
        """Shift of the second character after the first (binary search in KERNING)."""
        key = ord(first) << 8 | ord(second)
        low, high = 0, len(self.kerning) // 3
        while low < high:
            middle = (low + high) // 2
            record = middle * 3
            record_key = self.kerning[record] << 8 | self.kerning[record + 1]
            if record_key == key:
                return self.kerning[record + 2] - 48
            if record_key < key:
                low = middle + 1
            else:
                high = middle
        return 0

    def advance(self, text, i):
        """Distance from character i to the next one, including kerning."""
        advance = self.glyph(text[i])[0]
        if i + 1 < len(text):
            advance += self.kern(text[i], text[i + 1])
        return advance

    def textlength(self, text):
        return sum(self.advance(text, i) for i in range(len(text)))

    def draw(self, device, x, y, text):
        """Draw the text with its top left corner at x, y (like PIL's draw.text)."""
        for i, char in enumerate(text):
            _, x_offset, y_offset, width, height, start = self.glyph(char)
            if width:
                end = start + (width + 7) // 8 * height
                glyph = framebuf.FrameBuffer(
                    bytearray(self.data[start:end]), width, height, framebuf.MONO_HLSB
                )
                device.blit(glyph, x + x_offset, y + y_offset, 0)  # 0 = transparent
            x += self.advance(text, i)
